      ro: ["Adesea numit 'Marele Grânar'.", "Puternic afectat de inundații în sezonul ploios.", "Atmosferă liniștită, departe de turismul de masă.", "Are o piață veche fermecătoare."],
      en: ["Often called 'The Great Granary'.", "Heavily shaped by flooding during the wet season.", "Quiet atmosphere away from mass tourism.", "Features a charming old market."],
