      hu: ["Svay Rieng tartomány székhelye", "A Vayko-folyó partján fekszik", "Fontos határváros Vietnam felé", "A baveti gazdasági övezet központja", "Jelentős rizstermesztő vidék", "Az 1-es főút mentén található"],
