      es: ["Conecta las rutas entre Kratie y Mondulkiri.", "Lugar de un gran enfrentamiento en la guerra de Vietnam.", "Plantaciones de pasto y caucho rodean la ciudad.", "Lugar de fundación del Frente Unido de Camboya en 1978."],
      pt: ["Liga as rotas entre Kratie e Mondulkiri.", "Local de um grande confronto na Guerra do Vietnã.", "Plantações de capim e borracha cercam a cidade.", "Local de fundação da \"Frente Unida Cambojana\" em 1978."],
      fr: ["Relie les routes entre Kratie et le Mondulkiri.", "Lieu d'un affrontement majeur de la guerre du Vietnam.", "Des plantations d'herbe et de caoutchouc entourent la ville.", "Lieu de fondation du \"Front uni du Cambodge\" en 1978."],
