      en: ["The Battle of Snuol took place in May 1971 between US-backed forces and the NVA.", "Snuol is located approximately 80 kilometers southeast of the provincial capital, Kratie.", "The Trapaing Sre border crossing to Vietnam is located near Snuol.", "The Chup rubber plantations are among the largest in the region.", "The town is a major junction for travelers heading to Mondulkiri and Ratanakiri.", "Snuol was a significant base for the Ho Chi Minh Trail during the 1960s."],
      es: ["Población aprox. 35.000", "222 km al noreste de Phnom Penh", "Batalla de Snuol en mayo de 1970", "Fundación del KUFNS en 1978", "Protectorado francés desde 1863", "Gran zona de cultivo de caucho y anacardos", "Nudo hacia Mondulkiri y Vietnam", "Evacuada bajo los Jemeres Rojos 1975-1979"],
